package com.ptit.poker.admin.application;

import static com.ptit.poker.admin.application.AdminModels.*;import java.time.*;import java.util.Set;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;

@Service @Profile("!bootstrap") @Transactional(readOnly=true)
public class AdminQueryService {private static final Set<String> ROLES=Set.of("PLAYER","ADMIN"),ACCOUNTS=Set.of("ACTIVE","LOCKED"),ROOMS=Set.of("WAITING","PLAYING","FINISHED","CLOSED"),ROOM_TYPES=Set.of("PUBLIC","PRIVATE"),GAMES=Set.of("ACTIVE","FINISHED","ABORTED");private final AdminReadPort read;private final Clock clock;public AdminQueryService(AdminReadPort read,Clock clock){this.read=read;this.clock=clock;}
 public Overview overview(){return read.overview(clock.instant());}public Page<UserItem> users(int page,int size,String search,String status,String role){AdminQueryPolicy.pagination(page,size);return read.users(page,size,AdminQueryPolicy.optional(search),AdminQueryPolicy.allowed(status,ACCOUNTS),AdminQueryPolicy.allowed(role,ROLES));}public UserDetail user(long id){return read.user(id);}public Page<RoomItem> rooms(int page,int size,String search,String status,String type){AdminQueryPolicy.pagination(page,size);return read.rooms(page,size,AdminQueryPolicy.optional(search),AdminQueryPolicy.allowed(status,ROOMS),AdminQueryPolicy.allowed(type,ROOM_TYPES));}public RoomDetail room(long id){return read.room(id);}public Page<GameItem> games(int page,int size,String status,Long roomId,Long userId,Instant from,Instant to){AdminQueryPolicy.pagination(page,size);AdminQueryPolicy.dates(from,to);return read.games(page,size,AdminQueryPolicy.allowed(status,GAMES),roomId,userId,from,to);}public GameDetail game(long id){return read.game(id);}public Page<HandItem> hands(long id,int page,int size){AdminQueryPolicy.pagination(page,size);return read.hands(id,page,size);}
}
